import{_ as e,o as a,c as i,a3 as l}from"./chunks/framework.CRbjHCyB.js";const b=JSON.parse('{"title":"Lint","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Lint | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/features/lint"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/features/lint"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/features/lint"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/features/lint"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/features/lint"}]]},"headers":[],"relativePath":"zh/clice/features/lint.md","filePath":"zh/clice/features/lint.md","lastUpdated":1788607959000}'),s={name:"zh/clice/features/lint.md"};function c(n,t,o,r,d,h){return a(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="lint" tabindex="-1">Lint <a class="header-anchor" href="#lint" aria-label="Permalink to &quot;Lint&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>clice 将 clang-tidy 集成为内置 Lint 引擎。独立运行的 clang-tidy 会分别处理每个 TU，而 clice 的架构支持跨 TU 协调，从而消除重复工作。</p><p><strong>用法</strong>：<code>clice lint [--workspace &lt;dir&gt;] [--workers &lt;n&gt;] [--index]</code></p><p>对编译数据库中的每个翻译单元运行 clang-tidy，并使用 worker 池处理， 输出诊断；发现问题时以非零状态退出。 <code>--index</code> 还会利用同一批解析结果构建并持久化项目索引， 因此后续运行 <code>clice index</code> 时无需再执行任何操作。</p><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 通过 CLI 进行项目级 Lint（<code>clice lint</code>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 基础 clang-tidy 集成（单 TU、编辑器内诊断）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 跨 TU 头文件去重</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 增量重新执行 Lint（仅检查已变更的文件）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Lint 结果缓存</li></ul><h2 id="跨-tu-优化" tabindex="-1">跨 TU 优化 <a class="header-anchor" href="#跨-tu-优化" aria-label="Permalink to &quot;跨 TU 优化&quot;">​</a></h2><h3 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>clang-tidy 会单独处理每个翻译单元。一个被 N 个源文件包含的头文件会被检查 N 次——这种成倍增加的开销会拖慢大型代码库的项目级 Lint。</p><h3 id="clice-的方案" tabindex="-1">clice 的方案 <a class="header-anchor" href="#clice-的方案" aria-label="Permalink to &quot;clice 的方案&quot;">​</a></h3><p>作为掌握完整编译图的常驻服务器，clice 可以：</p><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 跟踪哪些头文件在多个 TU 间共享</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 计算声明内容的哈希值，跳过对先前 TU 中已出现的相同声明的重复检查</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 根据依赖关系调度 Lint 作业（对共享头文件只执行一次 Lint，并传播结果）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 以内容哈希值和检查配置为键，缓存各头文件的 Lint 结果</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 单文件诊断去重（基础：移除单个 TU 内的重复项）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 项目级诊断去重（高级：同一头文件中跨 TU 出现的相同警告 → 只显示一次）</li></ul><h3 id="预期加速效果" tabindex="-1">预期加速效果 <a class="header-anchor" href="#预期加速效果" aria-label="Permalink to &quot;预期加速效果&quot;">​</a></h3><p>对于有 H 个共享头文件和 N 个 TU 的项目，独立运行的 clang-tidy 的工作量为 O(N × H)。借助跨 TU 去重，clice 专为增量检查而设计——目标是无论被多少个 TU 包含，每个头文件都只检查一次。</p><h2 id="clang-tidy-集成质量" tabindex="-1">clang-tidy 集成质量 <a class="header-anchor" href="#clang-tidy-集成质量" aria-label="Permalink to &quot;clang-tidy 集成质量&quot;">​</a></h2><p>影响语言服务器中 clang-tidy 诊断质量的问题：</p><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 抑制系统头文件中宏产生的 clang-tidy 警告（<a href="https://github.com/clangd/clangd/issues/1587" target="_blank" rel="noreferrer">clangd#1587</a>、<a href="https://github.com/clangd/clangd/issues/2000" target="_blank" rel="noreferrer">clangd#2000</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 对 Preamble 中的预处理指令（头文件保护、宏）执行检查（<a href="https://github.com/clangd/clangd/issues/2501" target="_blank" rel="noreferrer">clangd#2501</a>、<a href="https://github.com/clangd/clangd/issues/160" target="_blank" rel="noreferrer">clangd#160</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 可按检查类别配置诊断严重级别（<a href="https://github.com/clangd/clangd/issues/1937" target="_blank" rel="noreferrer">clangd#1937</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 支持加载 clang-tidy 插件（<a href="https://github.com/clangd/clangd/issues/1458" target="_blank" rel="noreferrer">clangd#1458</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 支持 Clang 静态分析器（<a href="https://github.com/clangd/clangd/issues/905" target="_blank" rel="noreferrer">clangd#905</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 应用 clang-tidy 修复时清理替换项（<a href="https://github.com/clangd/clangd/issues/429" target="_blank" rel="noreferrer">clangd#429</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 按版本控制差异过滤诊断（<a href="https://github.com/clangd/clangd/issues/822" target="_blank" rel="noreferrer">clangd#822</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 通过 NOLINT / NOLINTNEXTLINE / NOLINTBEGIN-END 注释抑制诊断</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <code>.clangd</code> 配置中的 <code>Diagnostics.ClangTidy</code> 配置项</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 用于提升 clang-tidy 性能的快速检查过滤</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 将 clang-tidy 的 fix-it 建议作为代码操作</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 诊断元数据：检查名称、文档 URL、来源标签</li></ul><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>检查项选择目前使用内置的快速检查集，以及配置规则中针对各文件的 编译标志。标准 <code>.clang-tidy</code> 配置文件的自动发现机制尚未接入。</p>',20)])])}const p=e(s,[["render",c]]);export{b as __pageData,p as default};
